def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'
    if n == 2:
        return 'D'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_def = sum(1 for a in opp if a == 'D')

    if opp_def == 0 and n >= 4:
        return 'D'

    if opp_def > n * 0.6:
        return 'D'

    if n == 99:
        return 'D'

    if n == 98:
        retaliated = False
        for i in range(n - 1):
            if my[i] == 'D' and opp[i + 1] == 'D':
                retaliated = True
                break
        if retaliated:
            return 'C'
        else:
            return 'D'

    last_opp = opp[-1]
    if last_opp == 'C':
        return 'C'
    else:
        if len(my) >= 2 and ('D' in my[-2:]):
            return 'C'
        else:
            return 'D'
